  `target_id` bigint(20) NOT NULL,
  `status` varchar(10) NOT NULL DEFAULT 'pending' COMMENT 'pending | active | declined | stopped | expired',
  `requester_lat` double DEFAULT NULL,
  `requester_lng` double DEFAULT NULL,
