CREATE TABLE `place_entrances` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `place_id` bigint(20) NOT NULL,
  `name` varchar(100) DEFAULT NULL,
  `type` varchar(15) NOT NULL DEFAULT 'main' COMMENT 'main | side | gate | vehicle_in | vehicle_out',
  `lat` double NOT NULL,
  `lng` double NOT NULL,
  `geom` point NOT NULL,
  `node_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  SPATIAL KEY `geom` (`geom`),
  KEY `fk_entrance_place` (`place_id`),
  KEY `fk_entrance_node` (`node_id`),
  CONSTRAINT `fk_entrance_node` FOREIGN KEY (`node_id`) REFERENCES `road_nodes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_entrance_place` FOREIGN KEY (`place_id`) REFERENCES `places` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=181 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
