--
-- Table structure for table `places`
--

DROP TABLE IF EXISTS `places`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `places` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `slug` varchar(60) NOT NULL,
  `category_id` int(11) NOT NULL,
  `category_label` varchar(50) DEFAULT NULL,
  `name` varchar(200) NOT NULL,
  `aliases` text DEFAULT NULL COMMENT 'Từ khóa không dấu để tìm kiếm',
  `name_search` varchar(200) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `image_url` text DEFAULT NULL,
  `lat` double NOT NULL,
  `lng` double NOT NULL,
  `geom` point NOT NULL,
  `coverage_json` text DEFAULT NULL,
  `status` varchar(15) NOT NULL DEFAULT 'active' COMMENT 'active | maintenance | closed',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `show_label` tinyint(1) DEFAULT NULL COMMENT 'NULL=theo mac dinh danh muc, 0=an rieng, 1=hien rieng',
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  UNIQUE KEY `uq_places_slug` (`slug`),
  SPATIAL KEY `geom` (`geom`),
  KEY `fk_places_category` (`category_id`),
  KEY `idx_places_name_search` (`name_search`),
  CONSTRAINT `fk_places_category` FOREIGN KEY (`category_id`) REFERENCES `place_categories` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=98 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

