--
-- Table structure for table `rooms`
--

DROP TABLE IF EXISTS `rooms`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `rooms` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `floor_id` bigint(20) NOT NULL,
  `code` varchar(20) NOT NULL,
  `name` varchar(150) DEFAULT NULL,
  `room_type` varchar(15) NOT NULL COMMENT 'classroom | lab | office | support | stairs | elevator | wc | corridor | other',
  `svg_element_id` varchar(60) DEFAULT NULL,
  `plan_x` decimal(6,3) DEFAULT NULL COMMENT '% theo chiều ngang sơ đồ',
  `plan_y` decimal(6,3) DEFAULT NULL COMMENT '% theo chiều dọc sơ đồ',
  `layout_row` smallint(6) DEFAULT NULL,
  `layout_col` smallint(6) DEFAULT NULL,
  `capacity` int(11) DEFAULT NULL,
  `department` varchar(150) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `status` varchar(15) NOT NULL DEFAULT 'active' COMMENT 'active | maintenance | closed',
  `layout_colspan` smallint(6) NOT NULL DEFAULT 1,
  `layout_rowspan` smallint(6) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_floor_room_code` (`floor_id`,`code`),
  UNIQUE KEY `uq_floor_svg_element` (`floor_id`,`svg_element_id`),
  CONSTRAINT `fk_rooms_floor` FOREIGN KEY (`floor_id`) REFERENCES `floors` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5335 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

